using UnityEngine;

public class LifecycleDemo : MonoBehaviour
{
    private Rigidbody2D _rb;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>(); // 自身引用先取
    }

    private void Start()
    {
        // 依赖其他系统就绪后的逻辑
    }

    private void FixedUpdate()
    {
        _rb.linearVelocity = new Vector2(3f, _rb.linearVelocity.y);
    }
}
